package carrerforge.controller;
import carrerforge.dto.*;import carrerforge.service.JobApplicationService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@CrossOrigin(origins="${app.cors.allowed-origin:http://localhost:5173}") @RestController @RequestMapping("/api/applications")
public class JobApplicationController {private final JobApplicationService service;public JobApplicationController(JobApplicationService service){this.service=service;}@PostMapping @ResponseStatus(HttpStatus.CREATED) public ApplicationResponse apply(@Valid @RequestBody ApplicationRequest request){return service.apply(request);}@GetMapping public List<ApplicationResponse> all(){return service.all();}@GetMapping("/{id}") public ApplicationResponse get(@PathVariable Long id){return service.get(id);}@GetMapping("/user/{userId}") public List<ApplicationResponse> user(@PathVariable Long userId){return service.user(userId);}@GetMapping("/job/{jobId}") public List<ApplicationResponse> job(@PathVariable Long jobId){return service.job(jobId);}}
